def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    out = np.zeros((h * h, w * w), dtype=int)
    emit(out, "Allocate an empty canvas 3x the input size; each input cell owns one block.")
    for i in range(h):
        for j in range(w):
            if g[i, j] == 2:
                out[i*h:(i+1)*h, j*w:(j+1)*w] = g
                emit(out, f"Input cell ({i},{j}) is 2, so stamp a copy of the input into block ({i},{j}).")
    emit(out, "All blocks under colour-2 cells are filled; the rest stay 0.")
    return out
